#define LOAD() do { r2 = g[2]; r3 = g[3]; r4 = g[4]; r5 = g[5]; r6 = g[6]; r7 = g[7]; r8 = g[8]; r9 = g[9]; r10 = g[10]; } while (0)
    // L_2D98
    COV(154);
    r10 = spu_ori(r4, 0);
    goto L_2DA0;
L_2DA0:
    COV(155);
    r8 = spu_ori(r6, 0);
    goto L_2DA4;
